import test from'node:test';import assert from'node:assert/strict';import fs from'node:fs';
const R=p=>JSON.parse(fs.readFileSync(new URL('../'+p,import.meta.url)));
test('October 4 counts only two genuine deliveries and preserves seven gaps',()=>{const b=R('assets/citizen-work.json'),d=b.deliveries.filter(d=>d.executionId==='daily-20261004-root');assert.deepEqual(d.map(x=>x.citizenId).sort(),['saeon','vox']);assert.ok(d.every(d=>d.review===null));const f=R('assets/research-frontiers.json');for(const id of ['nullroute','sigma','leimma','pharma','runo','cynosure','memoria'])for(const l of ['zh','en','ko'])assert.ok(f.citizens[id][l].some(r=>r.observationId===`2026-10-04-gap-${id}`&&!r.publicationId));});
test('October 4 editions retain sources, caveats and actual attachments',()=>{for(const id of ['saeon','vox']){const n=R(`research/2026-10-04/${id}.json`);for(const l of ['zh','en','ko'])assert.ok(n.title[l]&&n.lead[l]&&n.limitation[l]);for(const a of n.attachments)assert.ok(fs.existsSync(new URL('../'+a.path,import.meta.url)));}const s=R('research/2026-10-04/source-checks.json');assert.equal(s.sources[0].total,2385);assert.equal(s.sources[1].eventDate,'2026-10-02');assert.equal(s.sources[2].sameBytesAsPreviousFetch,true);});
